-- Minimal relational schema for the actual POS functions and loyalty triggers.
 CREATE ROLE anon; CREATE ROLE authenticated;
 CREATE TYPE public.business_line AS ENUM ('car_wash','barbershop');
 CREATE TYPE public.ticket_item_type AS ENUM ('service','product');
 CREATE SCHEMA auth;
 CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
 CREATE TABLE profiles(id uuid PRIMARY KEY,role text,active boolean DEFAULT true);
 CREATE TABLE customers(id bigint PRIMARY KEY,is_general boolean DEFAULT false,loyalty_visits int DEFAULT 0,
 loyalty_last_visit timestamptz,loyalty_free_washes_earned int DEFAULT 0,loyalty_free_washes_used int DEFAULT 0);
 CREATE TABLE services(id bigint PRIMARY KEY,name text,is_extra boolean DEFAULT false,is_active boolean DEFAULT true,business_line public.business_line DEFAULT 'car_wash');
 CREATE TABLE tickets(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id bigint REFERENCES customers,
 ticket_number text, status text DEFAULT 'paid',business_line public.business_line DEFAULT 'car_wash',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),
 total numeric(10,2),vehicle_plate text,vehicle_type_id int,user_id uuid,loyalty_reward_id int,is_loyalty_redemption boolean,loyalty_original_amount numeric);
 CREATE TABLE ticket_items(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ticket_id bigint REFERENCES tickets ON DELETE CASCADE,
 service_id bigint REFERENCES services,item_type public.ticket_item_type DEFAULT 'service',service_name_snapshot text,price numeric(10,2),price_snapshot numeric(10,2),quantity int DEFAULT 1,discount_reason text,product_id bigint);
 CREATE TABLE payments(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ticket_id bigint REFERENCES tickets ON DELETE CASCADE,amount numeric(10,2),
 currency text DEFAULT 'NIO',exchange_rate numeric DEFAULT 36.5,payment_method text DEFAULT 'cash',amount_received numeric,change_amount numeric);
 CREATE TABLE ticket_mixed_payments(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ticket_id bigint REFERENCES tickets ON DELETE CASCADE,
 method text,currency text,amount numeric,exchange_rate numeric,amount_nio numeric,applied_nio numeric,change_nio numeric);
 CREATE TABLE membership_plans(id bigint PRIMARY KEY,duration_days int);
 CREATE TABLE customer_memberships(id bigint PRIMARY KEY,customer_id bigint,service_id bigint,washes_used int,total_washes_allowed int,active boolean,expires_at timestamptz,plan_id bigint,created_at timestamptz DEFAULT now());
 CREATE TABLE membership_washes(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ticket_id bigint REFERENCES tickets ON DELETE CASCADE,
 membership_id bigint REFERENCES customer_memberships,service_id bigint,is_bonus boolean);
 CREATE TABLE loyalty_programs(id int PRIMARY KEY,name text,slug text,cycle_size int,rewards jsonb,active boolean DEFAULT true);
 CREATE TABLE loyalty_progress(id serial PRIMARY KEY,customer_id bigint REFERENCES customers,program_id int REFERENCES loyalty_programs,
 total_washes int,washes_in_cycle int,cycle_number int,updated_at timestamptz,UNIQUE(customer_id,program_id));
 CREATE TABLE loyalty_rewards(id serial PRIMARY KEY,customer_id bigint REFERENCES customers,program_id int REFERENCES loyalty_programs,
 reward_name text,reward_slug text,status text DEFAULT 'available',earned_at timestamptz DEFAULT now(),expires_at timestamptz,
 ticket_id bigint REFERENCES tickets ON DELETE SET NULL,option_group text,option_slug text,selected_option text,selected_at timestamptz);
 CREATE TABLE loyalty_wash_log(id serial PRIMARY KEY,customer_id bigint,program_id int,ticket_id bigint REFERENCES tickets ON DELETE SET NULL,
 service_id bigint,wash_number int,user_id uuid,reward_earned_id int,created_at timestamptz DEFAULT now());
 CREATE TABLE loyalty_redemptions(id serial PRIMARY KEY,reward_id int REFERENCES loyalty_rewards,customer_id bigint,
 ticket_id bigint REFERENCES tickets ON DELETE SET NULL,user_id uuid,notes text,overridden_by_admin boolean,redeemed_at timestamptz DEFAULT now());
 CREATE TABLE loyalty_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id bigint,ticket_id bigint REFERENCES tickets ON DELETE SET NULL,
 service_id bigint,visit_number int,earned_free_wash boolean,created_at timestamptz DEFAULT now());
 CREATE TABLE products(id bigint PRIMARY KEY,name text,stock_quantity int CHECK(stock_quantity>=0),services_per_unit int,usage_count int,is_active boolean DEFAULT true,updated_at timestamptz, business_line public.business_line DEFAULT 'barbershop');
 CREATE TABLE stock_movements(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product_id bigint REFERENCES products,quantity_delta int,reason text,ticket_id bigint REFERENCES tickets ON DELETE SET NULL,user_id uuid);
 CREATE TABLE service_products(service_id bigint,product_id bigint REFERENCES products);
 CREATE TABLE inventory_test(ticket_id bigint,service_id int);
 CREATE FUNCTION public.record_service_inventory(p_service_id int,p_ticket_id bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql AS $$
 BEGIN IF p_service_id=99 THEN RAISE EXCEPTION 'Stock insuficiente'; END IF;
 INSERT INTO public.inventory_test VALUES(p_ticket_id,p_service_id); RETURN '{"ok":true}'; END $$;
 CREATE FUNCTION public.reverse_service_inventory(p_ticket_id bigint) RETURNS jsonb LANGUAGE plpgsql AS $$
 BEGIN DELETE FROM public.inventory_test WHERE ticket_id=p_ticket_id; RETURN '{"ok":true}'; END $$;

